# -*- coding: utf-8 -*-
"""Lecture 37 vignette pool A -- Respiratory infections: acute bronchitis, pneumonia types and presentation,
workup and severity (CURB-65 totals, PSI class from a given total, severe versus nonsevere), antibiotics by
setting, comorbidity, allergy and resistance risk, hospital and ventilator pneumonia, aspiration and lung
abscess (slides 15-56, 124-126).

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation.
EXPLANATIONS follow tools/question_writing/EXPLAIN_DEEP.md (2026-10-29): the key names the decisive clue and
the fact; each wrong choice says why it fails for THIS patient, the replacing fact, and a tell. Score items
show the item-by-item arithmetic.

Real-exam style (cms_exam_spec, 2026-10-29): multi-comorbidity "what instead" items (allergy, resistance,
comorbid disease) and score-from-the-vignette items (CURB-65 totals worked from the stem; PSI only as a given
total -> class, because the slide's PSI picture is cropped). Scope caps live in cms_e6l37_scope.py.
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e6l37_scope import *


def S(topic, io, q, opts, cite, slot):
    d = Q(topic, io, q, opts, cite); d["slot"] = slot; return d


def V(topic, io, q, opts, cite, slot, lead):
    d = S(topic, io, q, opts, cite, slot); d["lead"] = lead; return d


def ORD(d, asc):
    d["ordered"] = True; d["asc"] = asc; return d


